from __future__ import annotations

from fastapi.responses import HTMLResponse

from app.build_info import APP_VERSION, BUILD_ID


def device_analysis_page() -> HTMLResponse:
    return HTMLResponse(
        f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>NCT · Network Device Analysis</title>
<style>
:root{{--bg:#08141d;--panel:#0f1d27;--line:#294553;--text:#e7eef8;--muted:#9eb0b8;--accent:#57d6bf;--blue:#73bfff;--good:#61d095;--warn:#f4c95d;--bad:#ff7b7b;color-scheme:dark}}*{{box-sizing:border-box}}body{{margin:0;background:linear-gradient(135deg,#08141d,#10242e);color:var(--text);font:14px/1.45 system-ui,-apple-system,Segoe UI,sans-serif}}header,main{{max-width:1180px;margin:auto}}header{{position:sticky;top:0;z-index:100;padding:16px 0 14px;border-bottom:1px solid var(--line);background:rgba(8,20,29,.97);backdrop-filter:blur(14px)}}h1{{margin:0 0 4px;font-size:26px}}h2{{margin:0 0 8px;font-size:19px}}h3{{margin:18px 0 8px;font-size:15px}}.eyebrow{{color:var(--accent);font-weight:800;letter-spacing:.08em;text-transform:uppercase;font-size:11px}}.sub,.meta,.hint,.empty{{color:var(--muted)}}.sub{{margin:0}}.nav,.analysis-tabs,.actions,.evidence{{display:flex;flex-wrap:wrap;gap:8px;align-items:center}}.nav{{margin-top:12px}}.nav a,.analysis-tabs a,.evidence a{{border:1px solid #315264;background:#142d38;color:#b9cadc;border-radius:7px;padding:9px 13px;text-decoration:none;font-weight:700}}.nav a.active,.analysis-tabs a.active{{background:var(--accent);border-color:var(--accent);color:#07171b}}main{{padding:24px 0 60px}}.analysis-tabs{{margin-bottom:16px}}.analysis-tabs a{{padding:7px 11px}}.panel{{background:rgba(15,29,39,.95);border:1px solid var(--line);border-radius:12px;padding:18px;margin-bottom:18px;box-shadow:0 10px 35px #0003}}.picker{{display:grid;grid-template-columns:1.4fr 1.4fr auto auto;gap:10px;align-items:end}}label{{display:block;color:#bed0da;font-size:12px;font-weight:700;margin:4px 0 5px}}select,input{{width:100%;background:#0b1520;color:var(--text);border:1px solid #365268;border-radius:8px;padding:10px 11px;font:inherit}}button{{border:1px solid #3b6f91;background:#174665;color:#fff;border-radius:7px;padding:10px 14px;font:inherit;font-weight:750;cursor:pointer}}button.secondary{{background:transparent;border-color:#49617d}}button:disabled{{opacity:.5;cursor:not-allowed}}.status{{min-height:22px;margin-top:10px;color:var(--muted)}}.status.good{{color:var(--good)}}.status.warn{{color:var(--warn)}}.status.bad{{color:var(--bad)}}.cards{{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:9px;margin:13px 0}}.card{{background:#0a1720;border:1px solid var(--line);border-radius:8px;padding:10px}}.card strong{{display:block;color:var(--blue);font-size:20px}}.identity{{display:grid;grid-template-columns:repeat(4,1fr);gap:9px}}.identity div{{background:#0a1720;border:1px solid var(--line);border-radius:8px;padding:10px}}.identity span{{display:block;color:var(--muted);font-size:11px}}.two-column{{display:grid;grid-template-columns:1fr 1fr;gap:18px}}details{{border:1px solid var(--line);border-radius:9px;background:#0a1720;margin-top:9px}}summary{{cursor:pointer;padding:10px 12px;color:#dff7ff;font-weight:750}}.detail-body{{padding:0 12px 12px;overflow:auto}}table{{width:100%;border-collapse:collapse;min-width:560px}}th,td{{padding:8px 7px;text-align:left;vertical-align:top;border-bottom:1px solid #263f49;font-size:12px}}th{{color:var(--muted);font-size:10px;text-transform:uppercase}}code{{color:#9edcff}}.review{{border-left:4px solid var(--blue);padding:10px 12px;margin:8px 0;background:#0a1720;border-radius:7px}}.review.warning{{border-left-color:var(--warn)}}.review strong{{display:block}}.chip{{display:inline-block;margin:2px 5px 2px 0;padding:3px 7px;border-radius:99px;background:#243f4d;font-size:11px}}.change-grid{{display:grid;grid-template-columns:repeat(5,1fr);gap:8px}}.change-grid div{{background:#0a1720;border:1px solid var(--line);border-radius:8px;padding:9px}}.change-grid strong{{display:block;color:var(--blue);font-size:18px}}.hidden{{display:none!important}}.footer{{color:var(--muted);font-size:12px}}@media(max-width:1200px){{header,main{{padding-left:4vw;padding-right:4vw}}}}@media(max-width:850px){{.picker,.two-column{{grid-template-columns:1fr}}.cards{{grid-template-columns:repeat(2,1fr)}}.identity,.change-grid{{grid-template-columns:1fr 1fr}}}}
</style><style>.sr-only{{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}}.nct-brand{{display:flex;width:max-content;flex-direction:column;align-items:center;margin:0 auto;color:var(--text);line-height:1;text-align:center}}.nct-brand>strong{{padding-left:.24em;font-size:40px;letter-spacing:.24em}}.nct-brand span{{margin-top:3px;padding-top:3px;border-top:1px solid var(--accent);color:var(--muted);font-size:9px;font-weight:650;letter-spacing:.09em;text-transform:uppercase;white-space:nowrap}}.nct-brand span b{{color:var(--accent);font-size:1.16em;font-weight:950}}.nav{{justify-content:center;margin-top:8px!important}}.nav a{{padding-top:6px!important;padding-bottom:6px!important}}</style></head><body>
<header><h1 class="sr-only">Analyze</h1><div class="nct-brand" aria-label="NCT, Network Characterization Tool"><strong>NCT</strong><span><b>N</b>etwork <b>C</b>haracterization <b>T</b>ool</span></div><nav class="nav" aria-label="Primary"><a href="/scans">Nmap</a><a href="/device-config">Device</a><a class="active" href="/analysis" aria-current="page">Analyze</a><a href="/hunting">Hunt</a><a href="/network-map">Map</a></nav></header>
<main><nav class="analysis-tabs" aria-label="Analysis views"><a href="/analysis">Nmap Results</a><a class="active" href="/device-analysis" aria-current="page">Network Device Analysis</a></nav>
<section class="panel"><h2>Choose retained evidence</h2><p class="hint">Open one collection for analysis, or choose an older collection of the same device as a baseline.</p><div class="picker"><div><label for="currentRun">Collection to analyze</label><select id="currentRun"><option value="">Loading device collections…</option></select></div><div><label for="baselineRun">Optional comparison baseline</label><select id="baselineRun"><option value="">No comparison</option></select></div><button id="analyze">Analyze</button><button id="compare" class="secondary" disabled>Compare</button></div><div id="status" class="status" role="status"></div></section>
<section id="analysisPanel" class="hidden"><section class="panel"><div id="analysisHeading"></div><div id="identity" class="identity"></div><div id="cards" class="cards"></div><div id="evidence" class="evidence"></div></section><div class="two-column"><section class="panel"><h2>Review items</h2><div id="reviewItems"></div></section><section class="panel"><h2>Correlated evidence</h2><div id="correlations"></div></section></div><section class="panel"><h2>Routing and interfaces</h2><div id="routing"></div></section><section class="panel"><h2>Policy, NAT, and network objects</h2><div id="policy"></div></section></section>
<section id="comparisonPanel" class="panel hidden"><h2>Collection comparison</h2><div id="comparison"></div></section><div class="footer">Build <code>{APP_VERSION}</code> · <code>{BUILD_ID}</code></div></main>
<script>
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}}[c]));let records=[],current=null;
function setStatus(message,kind=''){{$('status').textContent=message;$('status').className='status '+kind}}
function when(value){{if(!value)return'—';const parsed=new Date(value);return Number.isNaN(parsed.valueOf())?value:parsed.toLocaleString()}}
function optionLabel(run){{const device=run.device_name||run.device_address||'Unknown device';return `${{device}} · ${{when(run.completed_at||run.created_at)}} · ${{run.status||'unknown'}}`}}
function collectionOptions(){{const selected=$('currentRun').value,requested=new URLSearchParams(location.search).get('run');$('currentRun').innerHTML='<option value="">Choose a collection…</option>'+records.map(run=>`<option value="${{esc(run.run_id)}}">${{esc(optionLabel(run))}}</option>`).join('');if(records.some(run=>run.run_id===(requested||selected)))$('currentRun').value=requested||selected;refreshBaselines();if(requested&&$('currentRun').value)analyze()}}
function refreshBaselines(){{const id=$('currentRun').value,run=records.find(item=>item.run_id===id),previous=records.filter(item=>item.run_id!==id&&(!run||item.device_address===run.device_address));$('baselineRun').innerHTML='<option value="">No comparison</option>'+previous.map(item=>`<option value="${{esc(item.run_id)}}">${{esc(optionLabel(item))}}</option>`).join('');$('compare').disabled=!id||!$('baselineRun').value}}
function table(items,columns){{if(!items?.length)return'<p class="empty">No retained evidence in this section.</p>';return`<div style="overflow:auto"><table><thead><tr>${{columns.map(c=>`<th>${{esc(c.label)}}</th>`).join('')}}</tr></thead><tbody>${{items.map(item=>`<tr>${{columns.map(c=>`<td>${{esc(typeof c.value==='function'?c.value(item):item[c.value])}}</td>`).join('')}}</tr>`).join('')}}</tbody></table></div>`}}
function detail(title,count,body,open=false){{return`<details${{open?' open':''}}><summary>${{esc(title)}} <span class="chip">${{Number(count||0)}}</span></summary><div class="detail-body">${{body}}</div></details>`}}
function renderAnalysis(data){{
  current=data;$('analysisPanel').classList.remove('hidden');
  const d=data.device||{{}},c=data.collection||{{}},counts=data.counts||{{}},routes=data.route_analysis||{{}};
  $('analysisHeading').innerHTML=`<h2>${{esc(d.name||d.address||'Network device')}}</h2><p class="meta">Analysis of collection ${{esc(data.run_id.slice(0,12))}} · ${{esc(c.status||'unknown')}} · ${{esc(when(c.completed_at||c.created_at))}}</p>`;
  $('identity').innerHTML=[['Address',d.address],['Vendor',d.vendor],['Device type',d.type],['Operator',c.operator]].map(([label,value])=>`<div><span>${{esc(label)}}</span><strong>${{esc(value||'—')}}</strong></div>`).join('');
  const cards=[['Interfaces',counts.interfaces],['Routes',counts.routes],['Default routes',counts.default_routes],['Next hops',counts.next_hops],['Policy / ACL',counts.firewall_acl],['Nmap hosts',counts.nmap_host_matches]];
  $('cards').innerHTML=cards.map(([label,value])=>`<div class="card"><strong>${{Number(value||0)}}</strong>${{esc(label)}}</div>`).join('');
  $('evidence').innerHTML=(data.evidence||[]).map(item=>`<a href="${{esc(item.url)}}" target="_blank" rel="noopener">${{esc(item.label)}}</a>`).join('');
  $('reviewItems').innerHTML=(data.review_items||[]).map(item=>`<div class="review ${{esc(item.severity)}}"><strong>${{esc(item.title)}}</strong><span class="meta">${{esc(item.category)}} · ${{esc(item.detail)}}</span>${{item.evidence?`<br><code>${{esc(item.evidence)}}</code>`:''}}</div>`).join('')||'<p class="status good">No review items were generated from the retained evidence.</p>';
  const saved=(data.saved_network_correlations||[]).map(item=>`<li><strong>${{esc(item.name)}}</strong> · <code>${{esc(item.cidr)}}</code> · <span class="chip">${{esc(item.confidence)}} confidence</span><br><span class="meta">Interfaces: ${{esc(item.interface_names.join(', ')||'—')}} · Routes: ${{esc(item.route_networks.join(', ')||'—')}} · Sources: ${{esc(item.provenance.join(', '))}}</span></li>`).join('');
  const hosts=(data.nmap_host_correlations||[]).map(item=>`<li><strong>${{esc(item.hostname||item.ip)}}</strong> · <code>${{esc(item.ip)}}</code> · ${{item.ports.length}} open service${{item.ports.length===1?'':'s'}} · <span class="chip">${{esc(item.confidence)}} confidence</span><br><span class="meta">${{esc(item.interface_networks.join(', '))}} · ${{item.sources.map(source=>`<a href="${{esc(source.url)}}" target="_blank" rel="noopener">${{esc(source.label)}}</a>`).join(', ')}}</span></li>`).join('');
  $('correlations').innerHTML=`<h3>Saved Networks</h3><ul>${{saved||'<li class="empty">No Saved Network matches.</li>'}}</ul><h3>Nmap hosts on device interfaces</h3><ul>${{hosts||'<li class="empty">No retained Nmap host matches.</li>'}}</ul>`;
  const protocolChips=Object.entries(routes.protocol_counts||{{}}).map(([name,count])=>`<span class="chip">${{esc(name)}} ${{count}}</span>`).join('');
  $('routing').innerHTML=`<div>${{protocolChips||'<span class="empty">No route protocols parsed.</span>'}}</div>${{detail('Interfaces',data.interfaces.length,table(data.interfaces,[{{label:'Interface',value:'name'}},{{label:'Address',value:'address'}},{{label:'Network',value:'network'}},{{label:'Role',value:'role'}},{{label:'Zone',value:'zone'}},{{label:'MAC',value:'mac'}}]),true)}}${{detail('Routes',routes.routes?.length,table(routes.routes,[{{label:'Network',value:'network'}},{{label:'Protocol',value:'protocol'}},{{label:'Type',value:'route_type'}},{{label:'Next hop',value:i=>i.via||'direct'}},{{label:'Interface',value:'interface'}},{{label:'Evidence',value:'line'}}]),true)}}${{detail('Next-hop summary',routes.next_hops?.length,table(routes.next_hops,[{{label:'Next hop',value:'address'}},{{label:'Routes',value:'route_count'}},{{label:'Networks',value:i=>i.networks.join(', ')}}]))}}${{detail('Multipath destinations',routes.multipath?.length,table(routes.multipath,[{{label:'Network',value:'network'}},{{label:'Paths',value:i=>i.paths.map(p=>`${{p.via||'direct'}}${{p.interface?' via '+p.interface:''}}`).join(' · ')}}]))}}`;
  const p=data.policy||{{}};
  $('policy').innerHTML=detail('Firewall / ACL evidence',p.firewall_acl?.length,table(p.firewall_acl,[{{label:'Line',value:'line_number'}},{{label:'Evidence',value:'evidence'}}]),true)+detail('NAT evidence',p.nat?.length,table(p.nat,[{{label:'Line',value:'line_number'}},{{label:'Evidence',value:'evidence'}}]))+detail('Network objects',p.network_objects?.length,table(p.network_objects,[{{label:'Line',value:'line_number'}},{{label:'Evidence',value:'evidence'}}]));
  $('analysisPanel').scrollIntoView({{behavior:'smooth',block:'start'}});
}}
async function analyze(){{const id=$('currentRun').value;if(!id){{setStatus('Choose a device collection first.','warn');return}}setStatus('Analyzing retained device evidence…');try{{const response=await fetch(`/api/device-analysis/${{encodeURIComponent(id)}}`),data=await response.json();if(!response.ok)throw new Error(data.detail||'Analysis failed');renderAnalysis(data);setStatus('Device analysis complete.','good')}}catch(error){{setStatus(error.message,'bad')}}}}
function deltaList(title,items,render){{return items?.length?`<h3>${{esc(title)}}</h3><ul>${{items.map(item=>`<li>${{esc(render(item))}}</li>`).join('')}}</ul>`:''}}
async function compare(){{
  const before=$('baselineRun').value,after=$('currentRun').value;if(!before||!after)return;
  setStatus('Comparing retained collections…');
  try{{
    const response=await fetch(`/api/device-analysis/compare?before=${{encodeURIComponent(before)}}&after=${{encodeURIComponent(after)}}`),data=await response.json();
    if(!response.ok)throw new Error(data.detail||'Comparison failed');
    const s=data.summary||{{}},p=data.policy_changes||{{}};
    $('comparisonPanel').classList.remove('hidden');
    $('comparison').innerHTML=`${{data.identity_mismatch?'<p class="status warn">These collections use different device addresses. Review identity before treating changes as a timeline.</p>':''}}<p class="meta">${{esc(optionLabel(records.find(r=>r.run_id===before)||{{}}))}} → ${{esc(optionLabel(records.find(r=>r.run_id===after)||{{}}))}}</p><div class="change-grid">${{Object.entries(s).map(([name,value])=>`<div><strong>${{value}}</strong>${{esc(name.replaceAll('_',' '))}}</div>`).join('')}}</div>${{deltaList('Interfaces added',data.interfaces_added,i=>`${{i.name}} · ${{i.address||'no address'}}`)}}${{deltaList('Interfaces removed',data.interfaces_removed,i=>`${{i.name}} · ${{i.address||'no address'}}`)}}${{deltaList('Interfaces changed',data.interfaces_changed,i=>`${{i.name}} · ${{Object.keys(i.changes).join(', ')}}`)}}${{deltaList('Routes added',data.routes_added,i=>`${{i.network}} via ${{i.via||'direct'}} · ${{i.protocol}}`)}}${{deltaList('Routes removed',data.routes_removed,i=>`${{i.network}} via ${{i.via||'direct'}} · ${{i.protocol}}`)}}${{deltaList('Firewall / ACL added',p.firewall_acl_added,i=>i.evidence)}}${{deltaList('Firewall / ACL removed',p.firewall_acl_removed,i=>i.evidence)}}${{deltaList('NAT added',p.nat_added,i=>i.evidence)}}${{deltaList('NAT removed',p.nat_removed,i=>i.evidence)}}${{deltaList('Network objects added',p.network_objects_added,i=>i.evidence)}}${{deltaList('Network objects removed',p.network_objects_removed,i=>i.evidence)}}`;
    setStatus('Collection comparison complete.','good');$('comparisonPanel').scrollIntoView({{behavior:'smooth',block:'start'}});
  }}catch(error){{setStatus(error.message,'bad')}}
}}
async function loadRecords(){{try{{const response=await fetch('/api/device-configs?limit=100'),data=await response.json();if(!response.ok)throw new Error(data.detail||'Device history unavailable');records=data;collectionOptions();setStatus(`${{records.length}} retained device collection${{records.length===1?'':'s'}} available.`,'good')}}catch(error){{setStatus(error.message,'bad')}}}}
$('currentRun').onchange=refreshBaselines;$('baselineRun').onchange=()=>{{$('compare').disabled=!$('baselineRun').value||!$('currentRun').value}};$('analyze').onclick=analyze;$('compare').onclick=compare;loadRecords();
</script></body></html>'''
    )
